using Microsoft.Data.SqlClient;

var connectionString = "Server=localhost;Database=AdventureWorks;User Id=sa;Password=YourStrong@Passw0rd;TrustServerCertificate=True";
await using var conn = new SqlConnection(connectionString);
await conn.OpenAsync();

await using var cmd = new SqlCommand("SELECT TOP 5 ProductID, Name FROM Production.Product", conn);
await using var reader = await cmd.ExecuteReaderAsync();

while (await reader.ReadAsync())
{
    Console.WriteLine($"{reader.GetInt32(0)}: {reader.GetString(1)}");
}
